cat > /tmp/find_functions.sh << 'EOF'
#!/bin/bash
extract_functions() {
    local file=$1
    local func_name=""

    awk 'NR==FNR {
        if (/^func /) {
            func_name=$0
        }
        if (/(\.GetUser|Store\.GetUser)/) {
            print func_name " — " FILENAME
            func_name=""
        }
    }' "$file" "$file" | sort -u
}

for file in "$@"; do
    extract_functions "$file"
done
EOF
chmod +x /tmp/find_functions.sh

# Get function names for each file
for file in /bench/repo/server/router/api/v1/auth_service.go /bench/repo/server/router/api/v1/auth_service_session.go /bench/repo/server/router/api/v1/auth_service_sso.go /bench/repo/server/router/api/v1/instance_service.go /bench/repo/server/router/api/v1/memo_service_webhooks.go /bench/repo/server/router/api/v1/shortcut_service.go /bench/repo/server/router/api/v1/user_service_access_tokens.go /bench/repo/server/router/api/v1/user_service_identities.go /bench/repo/server/router/api/v1/user_service_settings.go /bench/repo/server/router/api/v1/user_service_webhooks.go /bench/repo/server/router/fileserver/fileserver.go /bench/repo/server/router/rss/rss.go /bench/repo/server/auth/authenticator.go /bench/repo/server/notification/email.go /bench/repo/store/user_setting.go; do
    basename=$(basename "$file")
    count=$(grep -c "\.GetUser\|Store\.GetUser" "$file" 2>/dev/null || echo 0)
    if [ "$count" -gt 0 ]; then
        echo "$basename"
    fi
done
